  final String localPath;
  final BigInt maxBytes;
  final int maxEntries;
  final int permissions;
  final int modifiedSeconds;
  final AdbCompression compression;

  const AdbSyncRequest({
    required this.kind,
    required this.path,
    required this.localPath,
    required this.maxBytes,
    required this.maxEntries,
    required this.permissions,
    required this.modifiedSeconds,
    required this.compression,
  });

  @override
  int get hashCode =>
      kind.hashCode ^
      path.hashCode ^
      localPath.hashCode ^
      maxBytes.hashCode ^
      maxEntries.hashCode ^
      permissions.hashCode ^
      modifiedSeconds.hashCode ^
      compression.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is AdbSyncRequest &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          path == other.path &&
          localPath == other.localPath &&
          maxBytes == other.maxBytes &&
          maxEntries == other.maxEntries &&
          permissions == other.permissions &&
          modifiedSeconds == other.modifiedSeconds &&
          compression == other.compression;
}

/// TCP socket 选项；USB 连接不应用这些字段，但仍检查输入范围。
class AdbTcpOptions {
  final bool nodelay;
  final AdbKeepaliveOptions? keepalive;

  /// Android/Linux 的 TCP_USER_TIMEOUT；其他系统显式设置时返回不支持。
  final int? userTimeoutMs;

  const AdbTcpOptions({
    required this.nodelay,
    this.keepalive,
    this.userTimeoutMs,
  });

  static Future<AdbTcpOptions> default_() =>
      ScrcpyRustLib.instance.api.interopAdbApiApiAdbTcpOptionsDefault();

  @override
  int get hashCode =>
      nodelay.hashCode ^ keepalive.hashCode ^ userTimeoutMs.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is AdbTcpOptions &&
          runtimeType == other.runtimeType &&
          nodelay == other.nodelay &&
          keepalive == other.keepalive &&
          userTimeoutMs == other.userTimeoutMs;
}

/// 每端恰好提供路径或借入 FD。目标路径由本次复制独占创建，尚未提交时归 copy 句柄回收。
