  final Uint8List? sourcePath;
  final int? sourceFd;
  final Uint8List? targetPath;
  final int? targetFd;
  final BigInt sourceOffset;
  final BigInt? length;
  final LocalFileIdentity? expectedSource;
  final BigInt maxBytes;
  final int timeoutMs;

  const LocalFileCopyRequest({
    this.sourcePath,
    this.sourceFd,
    this.targetPath,
    this.targetFd,
    required this.sourceOffset,
    this.length,
    this.expectedSource,
    required this.maxBytes,
    required this.timeoutMs,
  });

  @override
  int get hashCode =>
      sourcePath.hashCode ^
      sourceFd.hashCode ^
      targetPath.hashCode ^
      targetFd.hashCode ^
      sourceOffset.hashCode ^
      length.hashCode ^
      expectedSource.hashCode ^
      maxBytes.hashCode ^
      timeoutMs.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is LocalFileCopyRequest &&
          runtimeType == other.runtimeType &&
          sourcePath == other.sourcePath &&
          sourceFd == other.sourceFd &&
          targetPath == other.targetPath &&
          targetFd == other.targetFd &&
          sourceOffset == other.sourceOffset &&
          length == other.length &&
          expectedSource == other.expectedSource &&
          maxBytes == other.maxBytes &&
          timeoutMs == other.timeoutMs;
}

